// Verify the HMAC signature: SHA-256(secret, `${ts}.${body}`)
const body = JSON.stringify(items[0].json);
const sig = $request.headers['x-mnemo-signature'];
const ts  = $request.headers['x-mnemo-timestamp'];
const now = Math.floor(Date.now() / 1000);
if (!sig || !ts || Math.abs(now - parseInt(ts, 10)) > 300) {
  throw new Error('Signature missing or timestamp outside replay window');
}
const crypto = require('crypto');
const secret = $env.MNEMO_WEBHOOK_HMAC_SECRET;
const expected = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
if (expected !== sig) { throw new Error('HMAC mismatch'); }
return items;

// Minimal Readability-style extraction. Workflow can be replaced with a
// trafilatura HTTP service in compose for higher fidelity.
const html = String(items[0].json.body || '');
const stripped = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const title = (html.match(/<title>([^<]+)<\/title>/i) || [])[1] || '';
return [{ json: { title, processed_content: stripped.slice(0, 60000), note_id: $node['Webhook (mnemo/001-url-ingest)'].json.note_id } }];

// Sign and forward the result back to the Mnemo API.
const body = JSON.stringify({
  note_id: items[0].json.note_id,
  title: items[0].json.title,
  processed_content: items[0].json.processed_content,
  extracted_metadata: { extracted_by: '001-url-ingest' },
});
const ts = String(Math.floor(Date.now() / 1000));
const crypto = require('crypto');
const secret = $env.MNEMO_WEBHOOK_HMAC_SECRET;
const sig = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, sig, idem: `001:${items[0].json.note_id}:${ts.slice(0,8)}` } }];
